import{CHARACTER_ERAS,EXTRA_CHARACTER_IDS,CHARACTER_NAMES,characterEra,isCharacterBoss,characterCleared,characterUnlockState}from'./character-roster.js?v=0.330.0';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function resolveCharacterDecks(data,registry){
 if(data?.schemaVersion!==1||data.characters?.length!==EXTRA_CHARACTER_IDS.length)throw Error('キャラクターデータの形式が正しくありません');const seen=new Set();
 return data.characters.map(h=>{const era=characterEra(h.id);if(!EXTRA_CHARACTER_IDS.includes(h.id)||seen.has(h.id)||h.name!==CHARACTER_NAMES[h.id]||h.era!==era?.id||!!h.boss!==isCharacterBoss(h.id))throw Error('キャラクターIDを確認してください');seen.add(h.id);const d={id:'character-'+h.id,name:h.name+' · '+h.title,format:'original',category:h.boss?'ボス':'キャラクター',cards:h.cards.map(r=>({...r})),hero:{...h,cards:undefined}};if(registry.validate(d).length||registry.coverage(d).unsupported||!h.signature?.length||h.signature.some(id=>!d.cards.some(r=>r.id===id)))throw Error(h.name+'の40枚構成を確認してください');return d;});
}
export function characterChallengeHTML(decks,eraId,state,{art=()=>'',ready=true}={}){
 const era=CHARACTER_ERAS.find(e=>e.id===eraId);if(!era)return'';const byId=new Map(decks.map(d=>[d.hero.id,d])),done=era.normal.filter(id=>characterCleared(id,state.progress,state.manualResults)).length;
 const card=(id,boss=false)=>{const d=byId.get(id);if(!d)return'';const h=d.hero,r=state.progress?.[id]||state.manualResults?.['character:'+id]||{},won=characterCleared(id,state.progress,state.manualResults),unlock=characterUnlockState(id,state),locked=boss&&!unlock.unlocked;
 return `<article class="hero-card character-card ${boss?'character-boss':''} ${locked?'character-locked':''}" style="--hero-accent:${esc(h.accent)}"><div class="hero-art" aria-hidden="true">${art(h.signature[0])}</div><div class="hero-content"><div class="row spread"><span class="hero-number">${boss?'BOSS':'CHALLENGER'}</span>${won?'<span class="badge green defeated-badge">✓ 撃破済み</span>':boss?`<span class="badge">${locked?'🔒 未解放':'解放済み'}</span>`:''}</div><h3>${esc(h.name)}</h3><strong>${esc(h.title)}</strong><p>${esc(h.description)}</p>${locked?`<div class="character-unlock" role="status">あと<strong>${unlock.remaining.length}人</strong>に勝利で解放<small>残り：${unlock.remaining.map(x=>esc(CHARACTER_NAMES[x])).join('、')}</small></div>`:''}<div class="hero-record"><span>通算</span><strong>${esc(r.wins||0)}勝 ${esc(r.losses||0)}敗</strong></div><div class="hero-buttons"><button class="btn primary" data-action="hero-start" data-id="${esc(d.id)}" ${!ready||locked?'disabled':''}>${locked?'🔒 解放待ち':won?'もう一度挑む':'挑む'}</button><button class="btn" data-action="hero-deck" data-id="${esc(d.id)}">40枚を見る</button></div></div></article>`;};
 return `<section class="character-era" aria-label="${era.label}チャレンジ"><div class="hero-intro"><span class="eyebrow">LEGEND DUEL</span><h2>${era.label}</h2><p>通常キャラ ${done} / ${era.normal.length}人 撃破</p><p class="small">通常キャラ全員に手動対戦で1勝すると、この世代のボスが解放されます。</p><progress class="character-progress" value="${done}" max="${era.normal.length}" aria-label="${era.label}の攻略状況"></progress></div><div class="hero-grid">${era.normal.map(id=>card(id)).join('')}</div><div class="hero-intro"><span class="eyebrow">UNLOCK BOSS</span><h2>決戦の相手</h2><p class="small">一度解放したボスには、何度でも挑戦できます。</p></div><div class="hero-grid">${era.bosses.map(id=>card(id,true)).join('')}</div></section>`;
}
